import re
import traceback
from typing import Literal
from celery.utils.serialization import UnpickleableExceptionWrapper

origins = Literal["integration", "trackstar"]


class PokedexException(Exception):
    def __init__(self, message, status_code, origin: origins):
        self.message = message
        self.status_code = status_code
        self.origin = origin
        super().__init__(self.message)


class ResourceNotFoundException(PokedexException):
    def __init__(self, resource, id, origin: origins = "trackstar"):
        name = resource.english_singular_name()
        msg = f"{name} `{id}` not found"
        super().__init__(msg, 404, origin)
        self.id = id
        # if you update this, update api.not_found_error_schema


class NotImplementedException(PokedexException):
    def __init__(self, method, endpoint, integration_name):
        msg = f"Endpoint {method} {endpoint} not implemented for {integration_name}"
        super().__init__(msg, 501, "trackstar")


class UnresolvableQueryException(Exception):
    # utils/crawl_dependencies.py found a query it can't map to a get function; we refuse
    # to produce an incomplete dependency map rather than guess
    pass


class RetryException(PokedexException):
    # anything worth another attempt. `retry` in utils.utils catches this, so a
    # subclass gets retried too, and the message stays whatever the caller said
    # went wrong rather than being forced into a rate-limit shape.
    # pass the vendor's status only when they really sent a 5xx, so the log says 504
    # not a flat 503. a 4xx, or a 200 with errors in the body, would blame us instead
    def __init__(self, message, retry_after_seconds=0, status_code=503):
        super().__init__(message, status_code, "integration")
        self.retry_after_seconds = retry_after_seconds

    def __reduce__(self):
        # celery pickles this to hand back to the caller and Exception.args only
        # carries the message, so the wait and the status would reset to defaults
        return (
            RetryException,
            (self.message, self.retry_after_seconds, self.status_code),
        )


class ThrottleException(RetryException):
    def __init__(self, integration_name, retry_after_seconds):
        msg = f"{integration_name} rate limit exceeded"
        super().__init__(msg, retry_after_seconds, 429)
        self.integration_name = integration_name

    def __reduce__(self):
        # without this celery rebuilds a throttle as the nearest ancestor it can
        # construct, RetryException, and the crawler stops seeing it as a throttle
        return (ThrottleException, (self.integration_name, self.retry_after_seconds))

    @classmethod
    def get_integration_name(cls, msg):
        pattern = re.compile(r"(.*) rate limit exceeded")
        match = pattern.match(msg)
        if match:
            return match.group(1)
        return ""


class InvalidTrackstarCredentialsException(PokedexException):
    def __init__(self, msg):
        super().__init__(msg, 401, "trackstar")


class InvalidCredentialsException(PokedexException):
    def __init__(self, integration_name, override: bool, message=""):
        if override != True:
            raise Exception(
                "This should only be used for integration.create_invalid_credentials_exception. Do you really mean to do this?"
            )
        msg = f"Invalid {integration_name} credentials"
        if message:
            msg += f": {message}"
        super().__init__(msg, 401, "integration")

    @classmethod
    def get_integration_name(cls, msg):
        pattern = re.compile(r"Invalid (.*) credentials")
        match = pattern.search(msg)
        if match:
            return match.group(1)
        return ""

    @classmethod
    def get_message(cls, msg):
        pattern = re.compile(r"Invalid .* credentials: (.*)")
        match = pattern.search(msg)
        if match:
            return match.group(1)
        return ""


class PermissionsException(PokedexException):
