class WriteNotReturnedException(PokedexException):
    # the vendor took the write but its read-back lags. a 409 so client libraries
    # don't auto-retry it the way they would a 5xx, which would write it twice
    def __init__(self, resource, id):
        name = resource.english_singular_name()
        msg = f"{name} `{id}` did not come back from the API in a reasonable time. It was most likely written successfully to the underlying integration, and will be populated on the next sync."
        super().__init__(msg, 409, "integration")
        self.resource = resource
        self.id = id

    def __reduce__(self):
        # Exception.args only carries the message, so unpickling would call
        # this with the wrong arguments
        return (WriteNotReturnedException, (self.resource, self.id))

