def test_update_product(self, integration, connection_row, request, context):
    try:
        super().test_update_product(integration, connection_row, request, context)
    except PokedexException as e:
        if "never returned updated product" in str(e):
            pytest.xfail(
                "shipfusion answers the PUT with success and never applies it to a "
                "product its own api created, so this cannot pass from our side (TRA-2776)"
            )
        raise e
    pytest.fail("shipfusion applied the update: drop this xfail (TRA-2776)")

